int mwifiex_enable_hs ( struct mwifiex_adapter * adapter ) { struct mwifiex_ds_hs_cfg hscfg ; struct mwifiex_private * priv ; int i ; if ( disconnect_on_suspend ) { for ( i = 0 ; i < adapter -> priv_num ; i ++ ) { priv = adapter -> priv [ i ] ; if ( priv ) { mwifiex_deauthenticate ( priv , NULL ) ; } } } priv = mwifiex_get_priv ( adapter , MWIFIEX_BSS_ROLE_STA ) ; if ( priv && priv -> sched_scanning ) { if ( priv -> wdev . wiphy -> wowlan_config && ! priv -> wdev . wiphy -> wowlan_config -> nd_config ) { mwifiex_dbg ( adapter , CMD , "aborting bgscan!\n" ) ; mwifiex_stop_bg_scan ( priv ) ; cfg80211_sched_scan_stopped ( priv -> wdev . wiphy , 0 ) ; } } if ( adapter -> hs_activated ) { mwifiex_dbg ( adapter , CMD , "cmd: HS Already activated\n" ) ; return true ; } adapter -> hs_activate_wait_q_woken = false ; hscfg . is_invoke_hostcmd = true ; adapter -> hs_enabling = true ; mwifiex_cancel_all_pending_cmd ( adapter ) ; if ( mwifiex_set_hs_params ( mwifiex_get_priv ( adapter , MWIFIEX_BSS_ROLE_STA ) , HostCmd_ACT_GEN_SET , MWIFIEX_SYNC_CMD , & hscfg ) ) { mwifiex_dbg ( adapter , ERROR , "IOCTL request HS enable failed\n" ) ; return false ; } if ( wait_event_interruptible_timeout ( adapter -> hs_activate_wait_q , adapter -> hs_activate_wait_q_woken , ( 10 * HZ ) ) <= 0 ) { mwifiex_dbg ( adapter , ERROR , "hs_activate_wait_q terminated\n" ) ; return false ; } return true ; } 